/*
  天工项目创建人修复（整份执行版）
  日期：2026-10-13

  作用：把 401 个天工项目在 AADP 中被错误写成技术账号（creator_id = 1）的创建人，
        改为天工 developer_project.creator_user_id 对应的真实用户（tiangong-noheader 账号）。

  执行方式：整个文件一次执行即可，不需要分批、不需要手动 COMMIT。推荐用文件导入（遇错自动停止）：
    mysql --default-character-set=utf8mb4 -h 主机 -P 端口 -u 用户 -p bote < 天工项目创建人修复_整份执行版_20261013.sql

  安全机制：
    - 清单写死在 fix_creator_list_20261013 表中（401 行），每行包含：AADP tenant_id、天工项目ID、天工团队ID、
      天工创建人ID、目标 creator_id。
    - 更新前逐行校验：项目仍有效、creator_id 仍为 1、天工项目ID和团队一致、目标用户有效、
      该行已成功备份。全部满足才更新；不满足的行自动跳过，并在最后的结果中列出原因。
    - 先整表备份 bt_tenant。备份失败（如备份表已存在）时校验无法通过，不会更新任何数据。
    - 重复执行安全：已改过的行 creator_id 不再是 1，会被跳过。

  执行后请把第四段「执行结果」的输出截图或复制发回确认。
  预期结果：total = 401，updated = 401，skipped = 0。
*/


/* ================================================================
   一、修复清单（写死）
   ================================================================ */
CREATE TABLE fix_creator_list_20261013 (
                                         tenant_id           BIGINT       NOT NULL PRIMARY KEY COMMENT 'AADP bt_tenant.tenant_id',
                                         ext_tenant_id       BIGINT       NOT NULL COMMENT '天工项目ID',
                                         tg_space_id         VARCHAR(64)  NOT NULL COMMENT '天工团队ID = bt_workspace.ext_space_id',
                                         creator_ext_user_id VARCHAR(64)  NOT NULL COMMENT '天工创建人ID',
                                         new_creator_id      BIGINT       NOT NULL COMMENT '目标 creator_id（tiangong-noheader 用户）',
                                         tenant_name         VARCHAR(256),
                                         check_ok            TINYINT      NOT NULL DEFAULT 0 COMMENT '1=校验通过',
                                         old_creator_id      BIGINT       NULL     COMMENT '更新前的 creator_id'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='天工项目创建人修复清单 20261013';



/* ================================================================
   二、整表备份 bt_tenant
   ================================================================ */
CREATE TABLE bak_bt_tenant_creator_20261013 LIKE bt_tenant;


/* ================================================================
   三、逐行校验 + 更新（自动提交）
   ================================================================ */

-- 3.1 逐行校验，全部满足才标记 check_ok = 1
UPDATE fix_creator_list_20261013 f
  JOIN bt_tenant t        ON t.tenant_id = f.tenant_id
  JOIN bt_workspace w     ON w.space_id = t.space_id
  JOIN bt_user u          ON u.user_id = f.new_creator_id
  JOIN bak_bt_tenant_creator_20261013 b ON b.tenant_id = f.tenant_id AND b.creator_id = 1
  SET f.check_ok = 1,
    f.old_creator_id = t.creator_id
WHERE t.status_cd = '00A'
  AND t.creator_id = 1
  AND t.ext_tenant_id = f.ext_tenant_id
  AND w.status_cd = '00A'
  AND w.ext_space_id = f.tg_space_id
  AND u.system_code = 'tiangong-noheader'
  AND u.ext_user_id = f.creator_ext_user_id
  AND u.status_cd = '00A'
  AND (u.user_state IS NULL OR u.user_state <> 'X');

-- 3.2 更新并提交
START TRANSACTION;

UPDATE bt_tenant t
  JOIN fix_creator_list_20261013 f ON f.tenant_id = t.tenant_id AND f.check_ok = 1
  SET t.creator_id   = f.new_creator_id,
    t.updator_id   = 1,
    t.updated_time = NOW()
WHERE t.creator_id = 1;

COMMIT;


/* ================================================================
   四、执行结果（请把这段输出发回确认）
   ================================================================ */

-- 4.1 汇总：预期 total=401, updated=401, skipped=0
SELECT COUNT(*)                                       AS total,
       SUM(t.creator_id = f.new_creator_id)           AS updated,
       SUM(t.creator_id IS NULL OR t.creator_id <> f.new_creator_id) AS skipped
FROM fix_creator_list_20261013 f
       LEFT JOIN bt_tenant t ON t.tenant_id = f.tenant_id;

-- 4.2 被跳过的行及原因（预期为空）
SELECT f.tenant_id, f.tenant_name, f.ext_tenant_id, t.status_cd, t.creator_id,
       CASE
         WHEN t.tenant_id IS NULL                       THEN '项目已不存在'
         WHEN t.status_cd <> '00A'                      THEN '项目已失效'
         WHEN t.ext_tenant_id <> f.ext_tenant_id        THEN '天工项目ID不一致'
         WHEN t.creator_id <> 1 AND f.check_ok = 0      THEN '执行前创建人已不是1，未修改'
         WHEN w.ext_space_id <> f.tg_space_id OR w.status_cd <> '00A' THEN '团队不一致或已失效'
         WHEN u.user_id IS NULL OR u.status_cd <> '00A' OR u.ext_user_id <> f.creator_ext_user_id
           OR u.system_code <> 'tiangong-noheader'   THEN '目标用户无效'
         WHEN f.check_ok = 0                            THEN '备份失败，未修改'
         ELSE '其他'
         END AS reason
FROM fix_creator_list_20261013 f
       LEFT JOIN bt_tenant t    ON t.tenant_id = f.tenant_id
       LEFT JOIN bt_workspace w ON w.space_id = t.space_id
       LEFT JOIN bt_user u      ON u.user_id = f.new_creator_id
WHERE t.creator_id IS NULL OR t.creator_id <> f.new_creator_id;


/* ================================================================
   五、回滚（只在出问题时执行；只恢复本次改过且之后未被再改动的行）
   ================================================================ */
/*
