JOIN bak_bt_tenant_creator_20261013 b ON b.tenant_id = t.tenant_id
SET t.creator_id = b.creator_id, t.updator_id = b.updator_id, t.updated_time = b.updated_time
WHERE t.creator_id = f.new_creator_id;
COMMIT;
*/
